import{_ as e,a,o as n,ai as i}from"./chunks/framework.BbOtTPsL.js";const l=JSON.parse('{"title":"Communications","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/communications/index.md","filePath":"api/rest-api/admin/marketing/communications/index.md","lastUpdated":1782473079000}'),o={name:"api/rest-api/admin/marketing/communications/index.md"};function r(s,t,m,d,c,h){return n(),a("div",null,t[0]||(t[0]=[i('<h1 id="communications" tabindex="-1">Communications <a class="header-anchor" href="#communications" aria-label="Permalink to &quot;Communications&quot;">​</a></h1><p>Communications is the store&#39;s <strong>outbound email</strong> toolkit — define a reusable email body, optionally anchor it to a dated event, then send it to a segment of subscribers. It mirrors the admin <strong>Marketing → Communications</strong> menu.</p><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/communications/templates/">Email Templates</a></td><td>Reusable HTML email bodies with a name and an active / inactive / draft status.</td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/events/">Events</a></td><td>Dated marketing events (e.g. a sale kickoff) that a campaign can be anchored to.</td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/campaigns/">Campaigns</a></td><td>A template sent to a customer group through a channel — optionally tied to an event. Includes a manual <strong>Send</strong>.</td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/subscribers/">Newsletter Subscribers</a></td><td>The audience — the email addresses that opted in on the storefront.</td></tr></tbody></table><h2 id="how-they-fit-together" tabindex="-1">How they fit together <a class="header-anchor" href="#how-they-fit-together" aria-label="Permalink to &quot;How they fit together&quot;">​</a></h2><p>A <strong>Campaign</strong> is the hub: it pairs an <strong>Email Template</strong> (the body) with a <strong>customer group</strong> of <strong>Newsletter Subscribers</strong> (the audience), sent over a <strong>channel</strong>, and may reference an <strong>Event</strong> (the occasion). Sending a campaign queues the template to every subscribed member of its customer group. Templates and events are reusable building blocks — many campaigns can share one template. Subscribers are created by the storefront opt-in, not through this API.</p><p>All Communications endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',7)]))}const p=e(o,[["render",r]]);export{l as __pageData,p as default};
